INSERT INTO posts VALUES(21,3,'Champion Burger a Westfield la Maquinista','Un grup d''estudiants i imbécils han anat a probar hamburgueses al event internacional de The Champions Burger.','2026-04-12 09:06:02','/storage/experiences/69e88f79eafe3_1776848761.webp',41.4461999999999974,2.19870000000000009,'ES','published','2026-04-22 09:06:02','2026-04-22 09:06:02');
INSERT INTO posts VALUES(22,3,'Tast de hamburgueses a Champion Burger','La primera hamburguesa que vam provar el Roger i jo va ser espectacular, la carn de wagyu del stand de ''El surtidor on fire'' es la millor que hem provat.','2026-03-31 09:06:02','/storage/experiences/69e88f7a3f54d_1776848762.webp',41.4461999999999974,2.19870000000000009,'ES','published','2026-04-22 09:06:02','2026-04-22 09:06:02');
INSERT INTO posts VALUES(23,5,'Voley i tirar pedres a la platja de Mataró','Tres individus van anar a passar el dia a la platja de Mataró, on a un li van fotre un cop amb la pilota de voley i després van anar a tirar pedres al mar. El dia va ser molt divertit i relaxant, amb molta sorra, poc sol i aigua molt freda.','2026-04-14 09:06:02','/storage/experiences/69e88f7a99ad6_1776848762.webp',41.5343000000000017,2.44759999999999999,'ES','published','2026-04-22 09:06:02','2026-04-22 09:06:02');
